import React, { useState } from "react";
import api from "../api/api";
import { useAuth } from "../context/AuthContext";

export default function Signup(){
  const [name,setName] = useState("");
  const [email,setEmail] = useState("");
  const [address,setAddress] = useState("");
  const [password,setPassword] = useState("");
  const { login } = useAuth();

  const submit = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post("/auth/signup", { name, email, address, password });
      login(res.data);
      window.location.href = "/dashboard";
    } catch (err) {
      alert(err?.response?.data?.message || "Signup failed");
    }
  };

  return (
    <div style={{padding:20}}>
      <h2>Signup</h2>
      <form onSubmit={submit}>
        <div><input placeholder="Full Name (20-60 chars)" value={name} onChange={e=>setName(e.target.value)} /></div>
        <div><input placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} /></div>
        <div><textarea placeholder="Address (max 400 chars)" value={address} onChange={e=>setAddress(e.target.value)} /></div>
        <div><input type="password" placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)} /></div>
        <button type="submit">Signup</button>
      </form>
    </div>
  );
}
